insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-13','en-a2-13',null,2,13,'published',1,'{"id":"en-a2-13","baseId":"en-a2-13","revision":1,"level":"A2","levelIndex":2,"order":13,"title":"Since, for va o‘tgan vaqtni tanlash","objective":"Davomiylikni boshlanish nuqtasidan ajratasiz va Perfect/Simple ni mos tanlaysiz.","context":"To‘garak a’zoligi va kechagi uchrashuv haqida yoziladi.","prerequisites":["en-a2-12"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang.","Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple.","Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring."],"pattern":"for two years / since 2024; have lived … / met yesterday","examples":["I have lived here for two years.","She has known Ali since 2024.","We met yesterday.","I joined the club last year.","I have been to Bukhara.","He has gone to the library."],"vocabulary":[{"id":"en-a2-13-v0","term":"since","meaning":"… dan beri","ipa":"/sɪns/","collocation":"since Monday","example":"She has known Ali since 2024."},{"id":"en-a2-13-v1","term":"for","meaning":"davomida","ipa":"/fɔː/","collocation":"for two years","example":"I have lived here for two years."},{"id":"en-a2-13-v2","term":"join","meaning":"qo‘shilmoq","ipa":"/dʒɔɪn/","collocation":"join a club","example":"I joined the club last year."},{"id":"en-a2-13-v3","term":"member","meaning":"a’zo","ipa":"/ˈmembə/","collocation":"a club member","example":"I have been a member for twelve months, and I have known our teacher since September."}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["for two years / since 2024; have lived … / met yesterday","I have lived here for two years.","She has known Ali since 2024."],"timeline":[{"why":"For two years boshlanishdan hozirgacha davomiylikni beradi. Grafikdagi uzunlik kunlar soni emas.","events":[{"kind":"span","from":110,"to":320,"label":"Ikki yil davomida — hozirgacha"}]},{"why":"Since 2024 boshlanish nuqtasi. Tanishlik hozirgacha davom etadi.","events":[{"kind":"span","from":95,"to":320,"label":"2024-yildan hozirgacha"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["To‘garak a’zoligi va kechagi uchrashuv haqida yoziladi.","We met yesterday.","I have been to Bukhara."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"I joined the club last year.","audio":"/english-course/v7.23/en-a2-13-dictation.mp3"},"exercises":[{"id":"en-a2-13-choice","type":"choice","skill":"grammar","prompt":"Tugallangan vaqt uchun mos gap?","answers":["We met yesterday."],"explanation":"Yesterday bilan Past Simple.","hint":"for two years / since 2024; have lived … / met yesterday","options":["We met yesterday.","We have met yesterday.","We has met yesterday."]},{"id":"en-a2-13-gap","type":"grammarFill","skill":"grammar","prompt":"I have known her ___ 2024.","answers":["since"],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday"},{"id":"en-a2-13-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I have lived here for two years."],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday","tokens":["I","have","lived","here","for","two","years."]},{"id":"en-a2-13-fix","type":"correction","skill":"grammar","prompt":"I have lived here since two years.","answers":["I have lived here for two years."],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday"},{"id":"en-a2-13-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["… dan beri","davomida","qo‘shilmoq","a’zo"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"for two years / since 2024; have lived … / met yesterday","left":["since","for","join","member"],"options":["… dan beri","davomida","qo‘shilmoq","a’zo"]}],"reading":{"title":"Since, for va o‘tgan vaqtni tanlash — vaziyat","text":"I joined our English club last year. I have been a member for twelve months, and I have known our teacher since September. Yesterday we met in the library and discussed a travel story. I have been to Bukhara, so I shared one memory. Ali has gone to the library now to return a book; he will come back later. Our group has studied together since autumn, but we did not meet during the school holiday.","sentences":["I joined our English club last year.","I have been a member for twelve months, and I have known our teacher since September.","Yesterday we met in the library and discussed a travel story.","I have been to Bukhara, so I shared one memory.","Ali has gone to the library now to return a book; he will come back later.","Our group has studied together since autumn, but we did not meet during the school holiday."],"questions":[{"id":"en-a2-13-reading0","type":"choice","skill":"reading","prompt":"Kecha nima qilishdi?","answers":["discussed a travel story"],"explanation":"Yesterday … discussed — tugallangan voqea.","hint":"for two years / since 2024; have lived … / met yesterday","options":["discussed a travel story","joined a new club","travelled to Bukhara"]},{"id":"en-a2-13-reading1","type":"choice","skill":"reading","prompt":"Ali hozir qayerga ketgan?","answers":["the library"],"explanation":"Has gone to the library, keyin qaytadi.","hint":"for two years / since 2024; have lived … / met yesterday","options":["the library","Bukhara","the park"]},{"id":"en-a2-13-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"for two years / since 2024; have lived … / met yesterday","options":["I joined our English club last year.","I have been a member for twelve months, and I have known our teacher since September.","Yesterday we met in the library and discussed a travel story.","I have been to Bukhara, so I shared one memory.","Ali has gone to the library now to return a book; he will come back later.","Our group has studied together since autumn, but we did not meet during the school holiday."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I have been in the club for twelve months. I have known the teacher since September. We met yesterday. Ali has gone to the library and will come back later.","audio":"/english-course/v7.23/en-a2-13.mp3","synthetic":true,"questions":[{"id":"en-a2-13-listening0","type":"choice","skill":"listening","prompt":"A’zolik muddati qancha?","answers":["twelve months"],"explanation":"For twelve months.","hint":"for two years / since 2024; have lived … / met yesterday","options":["twelve months","two weeks","six years"]},{"id":"en-a2-13-listening1","type":"choice","skill":"listening","prompt":"Ustozni qachondan taniydi?","answers":["September"],"explanation":"Since September.","hint":"for two years / since 2024; have lived … / met yesterday","options":["September","yesterday","last night"]},{"id":"en-a2-13-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["twelve months","September"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"for two years / since 2024; have lived … / met yesterday","rows":["Muddat","Boshlanish"]},{"id":"en-a2-13-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["I joined the club last year."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"for two years / since 2024; have lived … / met yesterday","audio":"/english-course/v7.23/en-a2-13-dictation.mp3","transcript":"I joined the club last year."}]},"writing":{"task":"Bir mashg‘ulotga qachon qo‘shilganingiz va qancha vaqtdan beri qatnashayotganingizni yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I joined the reading club last September. I have been a member for a year. I have known our teacher since the first meeting. Yesterday we discussed a story about a journey. I have been to Bukhara once, so I shared a memory. Our group has learned many useful words, and I still enjoy the meetings.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I have lived here for two years.","She has known Ali since 2024.","We met yesterday."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"For va since bilan ikki davomiylikni ayting, keyin aniq o‘tgan kun voqeasini qo‘shing.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Bir mashg‘ulotga qachon qo‘shilganingiz va qancha vaqtdan beri qatnashayotganingizni yozing.","exit":[[{"id":"en-a2-13-exit0","type":"grammarFill","skill":"grammar","prompt":"___ two years","answers":["for"],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday"},{"id":"en-a2-13-exit1","type":"grammarFill","skill":"grammar","prompt":"___ Monday","answers":["since"],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday"},{"id":"en-a2-13-exit2","type":"grammarFill","skill":"grammar","prompt":"I ___ the club last year. (join)","answers":["joined"],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday"},{"id":"en-a2-13-exit3","type":"choice","skill":"grammar","prompt":"Gone to nimani bildirishi mumkin?","answers":["away there now"],"explanation":"Kontekstda hali qaytmagan.","hint":"for two years / since 2024; have lived … / met yesterday","options":["away there now","always returned","never visited"]},{"id":"en-a2-13-exit4","type":"choice","skill":"grammar","prompt":"Been to tajriba gapimi?","answers":["Yes"],"explanation":"Borib ko‘rgan tajribasi.","hint":"for two years / since 2024; have lived … / met yesterday","options":["Yes","No","Only a future plan"]}],[{"id":"en-a2-13-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She has known Ali since 2024."],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday","tokens":["She","has","known","Ali","since","2024."]},{"id":"en-a2-13-exit-b1","type":"grammarFill","skill":"grammar","prompt":"___ Monday","answers":["since"],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday"},{"id":"en-a2-13-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I joined the club last year."],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday","tokens":["I","joined","the","club","last","year."]},{"id":"en-a2-13-exit-b3","type":"choice","skill":"grammar","prompt":"Gone to nimani bildirishi mumkin?","answers":["away there now"],"explanation":"Kontekstda hali qaytmagan.","hint":"for two years / since 2024; have lived … / met yesterday","options":["away there now","always returned","never visited"]},{"id":"en-a2-13-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["He has gone to the library."],"explanation":"For davomiy muddat: for two years. Since boshlanish nuqtasi: since 2024. Bularni bir-birining o‘rnida ishlatmang. Hali davom etayotgan holatda Present Perfect: I have lived here for two years. Kechagi tugallangan voqeada Past Simple. Have been to — borib ko‘rgan, qaytgan tajriba. Have gone to — hozir u yerga ketgan degan farqni kontekstda tekshiring.","hint":"for two years / since 2024; have lived … / met yesterday","tokens":["He","has","gone","to","the","library."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-14','en-a2-14',null,2,14,'published',1,'{"id":"en-a2-14","baseId":"en-a2-14","revision":1,"level":"A2","levelIndex":2,"order":14,"title":"Zero va First Conditional","objective":"Odatdagi natija bilan mumkin bo‘lgan kelajak shartini ajratasiz.","context":"Sinf sayrining ob-havoga bog‘liq rejasi tuziladi.","prerequisites":["en-a2-13"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple.","First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi.","Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang."],"pattern":"If + present, present / If + present, will + verb","examples":["If you heat ice, it melts.","If it rains, we will stay inside.","We will walk if the weather is good.","If you press this button, the light comes on.","If Ali arrives early, he will help us.","I will call you if the plan changes."],"vocabulary":[{"id":"en-a2-14-v0","term":"melt","meaning":"erimoq","ipa":"/melt/","collocation":"ice melts","example":"If you heat ice, it melts."},{"id":"en-a2-14-v1","term":"press","meaning":"bosmoq","ipa":"/pres/","collocation":"press a button","example":"If you press this button, the light comes on."},{"id":"en-a2-14-v2","term":"change","meaning":"o‘zgarmoq","ipa":"/tʃeɪndʒ/","collocation":"the plan changes","example":"I will call you if the plan changes."},{"id":"en-a2-14-v3","term":"weather","meaning":"ob-havo","ipa":"/ˈweðə/","collocation":"good weather","example":"We will walk if the weather is good."}],"visuals":[{"kind":"cause","title":"Ma’no va tuzilish","items":["If + present, present / If + present, will + verb","If you heat ice, it melts.","If it rains, we will stay inside."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinf sayrining ob-havoga bog‘liq rejasi tuziladi.","We will walk if the weather is good.","If Ali arrives early, he will help us."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"If you press this button, the light comes on.","audio":"/english-course/v7.23/en-a2-14-dictation.mp3"},"exercises":[{"id":"en-a2-14-choice","type":"choice","skill":"grammar","prompt":"Umumiy natijani tanlang.","answers":["If you heat ice, it melts."],"explanation":"Zero conditional umumiy qonuniyat.","hint":"If + present, present / If + present, will + verb","options":["If you heat ice, it melts.","If you heated ice, yesterday.","If ice will melts."]},{"id":"en-a2-14-gap","type":"grammarFill","skill":"grammar","prompt":"If it ___, we will stay inside. (rain)","answers":["rains"],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb"},{"id":"en-a2-14-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["If you heat ice, it melts."],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb","tokens":["If","you","heat","ice,","it","melts."]},{"id":"en-a2-14-fix","type":"correction","skill":"grammar","prompt":"If it will rain, we will stay inside.","answers":["If it rains, we will stay inside."],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb"},{"id":"en-a2-14-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["erimoq","bosmoq","o‘zgarmoq","ob-havo"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"If + present, present / If + present, will + verb","left":["melt","press","change","weather"],"options":["erimoq","bosmoq","o‘zgarmoq","ob-havo"]}],"reading":{"title":"Zero va First Conditional — vaziyat","text":"We are planning a science walk on Saturday. If the weather is good, we will visit the park and draw plants. If it rains, we will stay in the classroom and use photos. Our teacher shows us a lamp for the indoor activity. If you press its button, the light comes on. That is how the lamp normally works. Ali will bring paper if he arrives early. We will send everyone a message if the meeting place changes.","sentences":["We are planning a science walk on Saturday.","If the weather is good, we will visit the park and draw plants.","If it rains, we will stay in the classroom and use photos.","Our teacher shows us a lamp for the indoor activity.","If you press its button, the light comes on.","That is how the lamp normally works.","Ali will bring paper if he arrives early.","We will send everyone a message if the meeting place changes."],"questions":[{"id":"en-a2-14-reading0","type":"choice","skill":"reading","prompt":"Yomg‘ir yog‘sa nima qilishadi?","answers":["stay in the classroom"],"explanation":"If it rains, we will stay in the classroom.","hint":"If + present, present / If + present, will + verb","options":["stay in the classroom","cancel all learning","walk farther"]},{"id":"en-a2-14-reading1","type":"choice","skill":"reading","prompt":"Lamp haqidagi gap nimani aytadi?","answers":["a usual result"],"explanation":"Press button → light comes on odatiy natija.","hint":"If + present, present / If + present, will + verb","options":["a usual result","an impossible wish","a past event"]},{"id":"en-a2-14-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"If + present, present / If + present, will + verb","options":["We are planning a science walk on Saturday.","If the weather is good, we will visit the park and draw plants.","If it rains, we will stay in the classroom and use photos.","Our teacher shows us a lamp for the indoor activity.","If you press its button, the light comes on.","That is how the lamp normally works.","Ali will bring paper if he arrives early.","We will send everyone a message if the meeting place changes."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"If it rains on Saturday, we will stay inside. If the weather is good, we will visit the park. Press the lamp button: if you press it, the light comes on. I will call you if our plan changes.","audio":"/english-course/v7.23/en-a2-14.mp3","synthetic":true,"questions":[{"id":"en-a2-14-listening0","type":"choice","skill":"listening","prompt":"Yaxshi ob-havoda qayerga?","answers":["the park"],"explanation":"Will visit the park.","hint":"If + present, present / If + present, will + verb","options":["the park","the café","the station"]},{"id":"en-a2-14-listening1","type":"choice","skill":"listening","prompt":"Reja o‘zgarsa qanday xabar?","answers":["a call"],"explanation":"I will call you.","hint":"If + present, present / If + present, will + verb","options":["a call","a letter next month","no message"]},{"id":"en-a2-14-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Saturday","park"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"If + present, present / If + present, will + verb","rows":["Sayr kuni","Yaxshi ob-havodagi joy"]},{"id":"en-a2-14-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["If you press this button, the light comes on."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"If + present, present / If + present, will + verb","audio":"/english-course/v7.23/en-a2-14-dictation.mp3","transcript":"If you press this button, the light comes on."}]},"writing":{"task":"Tadbir uchun ikkita shartli reja va bir odatiy natija yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"If the weather is good, our class will visit the park. If it rains, we will work in the library. I will bring paper if we need to draw. The teacher will send a message if the meeting place changes. For our science activity, if you put ice in a warm room, it slowly melts.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["If you heat ice, it melts.","If it rains, we will stay inside.","We will walk if the weather is good."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Sherigingiz bilan ikki ehtimol uchun reja kelishing.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Tadbir uchun ikkita shartli reja va bir odatiy natija yozing.","exit":[[{"id":"en-a2-14-exit0","type":"grammarFill","skill":"grammar","prompt":"If she ___ early, she will help. (arrive)","answers":["arrives"],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb"},{"id":"en-a2-14-exit1","type":"grammarFill","skill":"grammar","prompt":"We ___ call you if it changes.","answers":["will"],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb"},{"id":"en-a2-14-exit2","type":"grammarFill","skill":"grammar","prompt":"If you heat ice, it ___.","answers":["melts"],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb"},{"id":"en-a2-14-exit3","type":"choice","skill":"grammar","prompt":"If qismiga odatda qaysi zamon?","answers":["Present Simple"],"explanation":"Real kelajak shartida present.","hint":"If + present, present / If + present, will + verb","options":["Present Simple","will + verb","Past Perfect always"]},{"id":"en-a2-14-exit4","type":"choice","skill":"grammar","prompt":"Umumiy natija qaysi?","answers":["Zero Conditional"],"explanation":"Zero odatiy natija.","hint":"If + present, present / If + present, will + verb","options":["Zero Conditional","only Past Simple","only a question"]}],[{"id":"en-a2-14-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If it rains, we will stay inside."],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb","tokens":["If","it","rains,","we","will","stay","inside."]},{"id":"en-a2-14-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We ___ call you if it changes.","answers":["will"],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb"},{"id":"en-a2-14-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["If you press this button, the light comes on."],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb","tokens":["If","you","press","this","button,","the","light","comes","on."]},{"id":"en-a2-14-exit-b3","type":"choice","skill":"grammar","prompt":"If qismiga odatda qaysi zamon?","answers":["Present Simple"],"explanation":"Real kelajak shartida present.","hint":"If + present, present / If + present, will + verb","options":["Present Simple","will + verb","Past Perfect always"]},{"id":"en-a2-14-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I will call you if the plan changes."],"explanation":"Zero Conditional odatiy yoki umumiy natija: If you heat ice, it melts. If + Present Simple, Present Simple. First Conditional real kelajak ehtimoli: If it rains, we will stay inside. If qismida odatda will emas, Present Simple keladi. Shart qismi avval kelsa vergul ishlatiladi. We will stay inside if it rains shaklida odatda vergul kerak emas. Umumiy hodisani shaxsiy rejadan farqlang.","hint":"If + present, present / If + present, will + verb","tokens":["I","will","call","you","if","the","plan","changes."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-15','en-a2-15',null,2,15,'published',1,'{"id":"en-a2-15","baseId":"en-a2-15","revision":1,"level":"A2","levelIndex":2,"order":15,"title":"Gerund va infinitive: niyat va yoqtirish","objective":"Enjoy doing va want to do kabi qoliplarni ajratasiz.","context":"O‘quvchi yangi to‘garak va til maqsadini tanlaydi.","prerequisites":["en-a2-14"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi.","Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join.","Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring."],"pattern":"enjoy doing / want to do / decide to join","examples":["I enjoy reading stories.","She wants to join the club.","We decided to study together.","He finished writing the email.","They plan to visit Bukhara.","I avoid using my phone in class."],"vocabulary":[{"id":"en-a2-15-v0","term":"decide","meaning":"qaror qilmoq","ipa":"/dɪˈsaɪd/","collocation":"decide to join","example":"We decided to study together."},{"id":"en-a2-15-v1","term":"avoid","meaning":"chetlab o‘tmoq","ipa":"/əˈvɔɪd/","collocation":"avoid using","example":"I avoid using my phone in class."},{"id":"en-a2-15-v2","term":"plan","meaning":"rejalashtirmoq","ipa":"/plæn/","collocation":"plan to visit","example":"They plan to visit Bukhara."},{"id":"en-a2-15-v3","term":"join","meaning":"qo‘shilmoq","ipa":"/dʒɔɪn/","collocation":"join a club","example":"She wants to join the club."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["enjoy doing / want to do / decide to join","I enjoy reading stories.","She wants to join the club."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘quvchi yangi to‘garak va til maqsadini tanlaydi.","We decided to study together.","They plan to visit Bukhara."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"He finished writing the email.","audio":"/english-course/v7.23/en-a2-15-dictation.mp3"},"exercises":[{"id":"en-a2-15-choice","type":"choice","skill":"grammar","prompt":"Decide bilan mos qolip?","answers":["decide to join"],"explanation":"Decide to do — qaror.","hint":"enjoy doing / want to do / decide to join","options":["decide to join","decide joining (ordinary intention)","decide joins"]},{"id":"en-a2-15-gap","type":"grammarFill","skill":"grammar","prompt":"She wants ___ join the club.","answers":["to"],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join"},{"id":"en-a2-15-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I enjoy reading stories."],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join","tokens":["I","enjoy","reading","stories."]},{"id":"en-a2-15-fix","type":"correction","skill":"grammar","prompt":"I enjoy to read.","answers":["I enjoy reading."],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join"},{"id":"en-a2-15-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qaror qilmoq","chetlab o‘tmoq","rejalashtirmoq","qo‘shilmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"enjoy doing / want to do / decide to join","left":["decide","avoid","plan","join"],"options":["qaror qilmoq","chetlab o‘tmoq","rejalashtirmoq","qo‘shilmoq"]},{"id":"en-a2-15-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["decide","avoid","plan","join"],"options":["decide to join","avoid using","plan to visit","join a club"],"answers":["decide to join","avoid using","plan to visit","join a club"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Gerund va infinitive: niyat va yoqtirish — vaziyat","text":"Lola enjoys reading, but she wants to improve her speaking too. She decides to join the English club. Ali plans to study with her twice a week. They finish writing their first short email and then practise a dialogue. During study time, they avoid using their phones for games. Their teacher asks them to choose a small goal, such as learning to ask for directions. They do not try to learn everything in one evening. A clear plan helps them practise regularly.","sentences":["Lola enjoys reading, but she wants to improve her speaking too.","She decides to join the English club.","Ali plans to study with her twice a week.","They finish writing their first short email and then practise a dialogue.","During study time, they avoid using their phones for games.","Their teacher asks them to choose a small goal, such as learning to ask for directions.","They do not try to learn everything in one evening.","A clear plan helps them practise regularly."],"questions":[{"id":"en-a2-15-reading0","type":"choice","skill":"reading","prompt":"Lola nimani rivojlantirmoqchi?","answers":["speaking"],"explanation":"Wants to improve her speaking too.","hint":"enjoy doing / want to do / decide to join","options":["speaking","only spelling","football"]},{"id":"en-a2-15-reading1","type":"choice","skill":"reading","prompt":"Nimadan qochishadi?","answers":["phone games during study"],"explanation":"Avoid using phones for games.","hint":"enjoy doing / want to do / decide to join","options":["phone games during study","all group work","reading stories"]},{"id":"en-a2-15-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"enjoy doing / want to do / decide to join","options":["Lola enjoys reading, but she wants to improve her speaking too.","She decides to join the English club.","Ali plans to study with her twice a week.","They finish writing their first short email and then practise a dialogue.","During study time, they avoid using their phones for games.","Their teacher asks them to choose a small goal, such as learning to ask for directions.","They do not try to learn everything in one evening.","A clear plan helps them practise regularly."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I enjoy reading, but I want to improve my speaking. I decided to join the club. Ali plans to study with me. We avoid using our phones for games while we study.","audio":"/english-course/v7.23/en-a2-15.mp3","synthetic":true,"questions":[{"id":"en-a2-15-listening0","type":"choice","skill":"listening","prompt":"So‘zlovchi nimani yoqtiradi?","answers":["reading"],"explanation":"Enjoy reading.","hint":"enjoy doing / want to do / decide to join","options":["reading","dancing","driving"]},{"id":"en-a2-15-listening1","type":"choice","skill":"listening","prompt":"Nimaga qo‘shilishga qaror qildi?","answers":["the club"],"explanation":"Decided to join the club.","hint":"enjoy doing / want to do / decide to join","options":["the club","the bus company","a football team"]},{"id":"en-a2-15-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["reading","speaking"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"enjoy doing / want to do / decide to join","rows":["Yoqtiradigan ish","Rivojlantiradigan ko‘nikma"]},{"id":"en-a2-15-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["He finished writing the email."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"enjoy doing / want to do / decide to join","audio":"/english-course/v7.23/en-a2-15-dictation.mp3","transcript":"He finished writing the email."}]},"writing":{"task":"Til o‘rganish rejangiz: yoqtiradigan ish, niyat, qaror va qochmoqchi odat haqida yozing.","audience":"Sinfdagi sherigingiz","minWords":55,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I enjoy watching short English videos, but I want to speak more confidently. I plan to practise with a friend twice a week. We decided to record a short dialogue and listen to it again. I avoid using my phone for games during study time. After finishing each exercise, I check why my answer was right or wrong.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I enjoy reading stories.","She wants to join the club.","We decided to study together."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Bir niyat va uni bajarish qarorini tushuntiring.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Til o‘rganish rejangiz: yoqtiradigan ish, niyat, qaror va qochmoqchi odat haqida yozing.","exit":[[{"id":"en-a2-15-exit0","type":"grammarFill","skill":"grammar","prompt":"He finished ___ the email. (write)","answers":["writing"],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join"},{"id":"en-a2-15-exit1","type":"grammarFill","skill":"grammar","prompt":"They plan ___ visit Bukhara.","answers":["to"],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join"},{"id":"en-a2-15-exit2","type":"grammarFill","skill":"grammar","prompt":"I avoid ___ my phone. (use)","answers":["using"],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join"},{"id":"en-a2-15-exit3","type":"choice","skill":"grammar","prompt":"Want bilan qaysi shakl?","answers":["to improve"],"explanation":"Want to improve.","hint":"enjoy doing / want to do / decide to join","options":["to improve","improving only","improves"]},{"id":"en-a2-15-exit4","type":"choice","skill":"grammar","prompt":"Enjoy reading to‘g‘rimi?","answers":["Yes"],"explanation":"Enjoy + -ing.","hint":"enjoy doing / want to do / decide to join","options":["Yes","No","Only in questions"]}],[{"id":"en-a2-15-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She wants to join the club."],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join","tokens":["She","wants","to","join","the","club."]},{"id":"en-a2-15-exit-b1","type":"grammarFill","skill":"grammar","prompt":"They plan ___ visit Bukhara.","answers":["to"],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join"},{"id":"en-a2-15-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["He finished writing the email."],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join","tokens":["He","finished","writing","the","email."]},{"id":"en-a2-15-exit-b3","type":"choice","skill":"grammar","prompt":"Want bilan qaysi shakl?","answers":["to improve"],"explanation":"Want to improve.","hint":"enjoy doing / want to do / decide to join","options":["to improve","improving only","improves"]},{"id":"en-a2-15-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I avoid using my phone in class."],"explanation":"Enjoy, finish, avoid kabi fe’llardan keyin -ing; want, plan, decide dan keyin to + asosiy fe’l ko‘p ishlatiladi. Bitta umumiy qoida barcha fe’llarni qamramaydi. Fe’lni keyingi qolipi bilan o‘rganing: enjoy reading, decide to join. Like doing va like to do ayrim vaziyatlarda ikkalasi ham mumkin. Enjoy to do esa standart emas. Xatoni aynan bosh fe’lga qarab tekshiring.","hint":"enjoy doing / want to do / decide to join","tokens":["I","avoid","using","my","phone","in","class."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a2-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a2-16','en-a2-16',null,2,16,'published',1,'{"id":"en-a2-16","baseId":"en-a2-16","revision":1,"level":"A2","levelIndex":2,"order":16,"title":"Somebody, anything va nowhere","objective":"Noma’lum odam, narsa yoki joy haqida gapirasiz.","context":"Kutubxonada qolgan sumkaning egasi qidiriladi.","prerequisites":["en-a2-15"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Someone/somebody — kimdir; something — nimadir; somewhere — qayerdir. Bu so‘zlar ko‘pincha tasdiqda.","Anyone/anything/anywhere savol va inkorda ko‘p uchraydi. Nobody/nothing/nowhere o‘zi inkor, qo‘shimcha not talab qilmaydi.","Someone va everyone grammatik birlik: Everyone is here. They ko‘pincha jinsi noma’lum shaxsga keyingi gapda neytral murojaat qiladi."],"pattern":"Someone is … / I didn’t see anyone. / Nobody is …","examples":["Someone left a bag here.","Does anyone know the owner?","I didn’t see anything inside.","Nobody is in the room.","Everyone is ready.","We can put it somewhere safe."],"vocabulary":[{"id":"en-a2-16-v0","term":"owner","meaning":"ega","ipa":"/ˈəʊnə/","collocation":"the bag’s owner","example":"Does anyone know the owner?"},{"id":"en-a2-16-v1","term":"safe","meaning":"xavfsiz","ipa":"/seɪf/","collocation":"somewhere safe","example":"We can put it somewhere safe."},{"id":"en-a2-16-v2","term":"inside","meaning":"ichida","ipa":"/ɪnˈsaɪd/","collocation":"look inside","example":"I didn’t see anything inside."},{"id":"en-a2-16-v3","term":"everyone","meaning":"hamma","ipa":"/ˈevriwʌn/","collocation":"everyone is ready","example":"Everyone is ready."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["Someone is … / I didn’t see anyone. / Nobody is …","Someone left a bag here.","Does anyone know the owner?"]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Kutubxonada qolgan sumkaning egasi qidiriladi.","I didn’t see anything inside.","Everyone is ready."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Nobody is in the room.","audio":"/english-course/v7.23/en-a2-16-dictation.mp3"},"exercises":[{"id":"en-a2-16-choice","type":"choice","skill":"grammar","prompt":"Inkor gapni to‘ldiring: I didn’t see ___.","answers":["anyone"],"explanation":"Any inkor bilan mos.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","options":["anyone","no one (double negative)","everyone is"]},{"id":"en-a2-16-gap","type":"grammarFill","skill":"grammar","prompt":"Everyone ___ ready.","answers":["is"],"explanation":"Someone/somebody — kimdir; something — nimadir; somewhere — qayerdir. Bu so‘zlar ko‘pincha tasdiqda. Anyone/anything/anywhere savol va inkorda ko‘p uchraydi. Nobody/nothing/nowhere o‘zi inkor, qo‘shimcha not talab qilmaydi. Someone va everyone grammatik birlik: Everyone is here. They ko‘pincha jinsi noma’lum shaxsga keyingi gapda neytral murojaat qiladi.","hint":"Someone is … / I didn’t see anyone. / Nobody is …"},{"id":"en-a2-16-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Someone left a bag here."],"explanation":"Someone/somebody — kimdir; something — nimadir; somewhere — qayerdir. Bu so‘zlar ko‘pincha tasdiqda. Anyone/anything/anywhere savol va inkorda ko‘p uchraydi. Nobody/nothing/nowhere o‘zi inkor, qo‘shimcha not talab qilmaydi. Someone va everyone grammatik birlik: Everyone is here. They ko‘pincha jinsi noma’lum shaxsga keyingi gapda neytral murojaat qiladi.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","tokens":["Someone","left","a","bag","here."]},{"id":"en-a2-16-fix","type":"correction","skill":"grammar","prompt":"Nobody isn’t here.","answers":["Nobody is here."],"explanation":"Someone/somebody — kimdir; something — nimadir; somewhere — qayerdir. Bu so‘zlar ko‘pincha tasdiqda. Anyone/anything/anywhere savol va inkorda ko‘p uchraydi. Nobody/nothing/nowhere o‘zi inkor, qo‘shimcha not talab qilmaydi. Someone va everyone grammatik birlik: Everyone is here. They ko‘pincha jinsi noma’lum shaxsga keyingi gapda neytral murojaat qiladi.","hint":"Someone is … / I didn’t see anyone. / Nobody is …"},{"id":"en-a2-16-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ega","xavfsiz","ichida","hamma"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","left":["owner","safe","inside","everyone"],"options":["ega","xavfsiz","ichida","hamma"]},{"id":"en-a2-16-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["Someone left a bag here."],"tokens":["Someone","left","a","bag","here."],"hint":"Someone is … / I didn’t see anyone. / Nobody is …","explanation":"Someone/somebody — kimdir; something — nimadir; somewhere — qayerdir. Bu so‘zlar ko‘pincha tasdiqda."},{"id":"en-a2-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Since, for va o‘tgan vaqtni tanlash: Tugallangan vaqt uchun mos gap?","answers":["We met yesterday."],"explanation":"Yesterday bilan Past Simple.","hint":"for two years / since 2024; have lived … / met yesterday","options":["We met yesterday.","We have met yesterday.","We has met yesterday."],"recap":true,"sourceLesson":"Since, for va o‘tgan vaqtni tanlash"},{"id":"en-a2-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Zero va First Conditional: Umumiy natijani tanlang.","answers":["If you heat ice, it melts."],"explanation":"Zero conditional umumiy qonuniyat.","hint":"If + present, present / If + present, will + verb","options":["If you heat ice, it melts.","If you heated ice, yesterday.","If ice will melts."],"recap":true,"sourceLesson":"Zero va First Conditional"},{"id":"en-a2-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Gerund va infinitive: niyat va yoqtirish: Decide bilan mos qolip?","answers":["decide to join"],"explanation":"Decide to do — qaror.","hint":"enjoy doing / want to do / decide to join","options":["decide to join","decide joining (ordinary intention)","decide joins"],"recap":true,"sourceLesson":"Gerund va infinitive: niyat va yoqtirish"}],"reading":{"title":"Somebody, anything va nowhere — vaziyat","text":"Someone left a blue bag in the library. The librarian asks if anyone knows the owner. Nobody in the room recognises it. There is something written on a label, but the name is difficult to read. The librarian does not open the bag. She puts it somewhere safe and tells the school office. Later, a student comes back for it. They describe the bag and show the same name on their notebook. Everyone is pleased that the bag is returned safely.","sentences":["Someone left a blue bag in the library.","The librarian asks if anyone knows the owner.","Nobody in the room recognises it.","There is something written on a label, but the name is difficult to read.","The librarian does not open the bag.","She puts it somewhere safe and tells the school office.","Later, a student comes back for it.","They describe the bag and show the same name on their notebook.","Everyone is pleased that the bag is returned safely."],"questions":[{"id":"en-a2-16-reading0","type":"choice","skill":"reading","prompt":"Kutubxonachi sumkani ochdimi?","answers":["No"],"explanation":"Does not open the bag.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","options":["No","Yes","Only the first pocket"]},{"id":"en-a2-16-reading1","type":"choice","skill":"reading","prompt":"Ega nima bilan tasdiqlanadi?","answers":["description and matching name"],"explanation":"Describe the bag and show the same name.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","options":["description and matching name","guessing its colour only","finding money"]},{"id":"en-a2-16-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","options":["Someone left a blue bag in the library.","The librarian asks if anyone knows the owner.","Nobody in the room recognises it.","There is something written on a label, but the name is difficult to read.","The librarian does not open the bag.","She puts it somewhere safe and tells the school office.","Later, a student comes back for it.","They describe the bag and show the same name on their notebook.","Everyone is pleased that the bag is returned safely."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Someone left a blue bag. Does anyone know the owner? Nobody here recognises it. We will put it somewhere safe and tell the school office. Please don’t open it.","audio":"/english-course/v7.23/en-a2-16.mp3","synthetic":true,"questions":[{"id":"en-a2-16-listening0","type":"choice","skill":"listening","prompt":"Sumka rangi?","answers":["blue"],"explanation":"Blue bag.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","options":["blue","black","green"]},{"id":"en-a2-16-listening1","type":"choice","skill":"listening","prompt":"Kimga xabar beriladi?","answers":["school office"],"explanation":"Tell the school office.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","options":["school office","a shop","the bus driver"]},{"id":"en-a2-16-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["blue","school office"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","rows":["Rang","Xabar joyi"]},{"id":"en-a2-16-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Nobody is in the room."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Someone is … / I didn’t see anyone. / Nobody is …","audio":"/english-course/v7.23/en-a2-16-dictation.mp3","transcript":"Nobody is in the room."}]},"writing":{"task":"Topilgan buyum haqida uning shaxsiy ichidagi ma’lumotni ochmasdan e’lon yozing.","audience":"Sinfdagi sherigingiz","minWords":53,"maxWords":140,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Someone left a blue bag in the library today. Nobody in our group knows the owner. The bag is now somewhere safe in the school office. Please ask a teacher if it is yours. You should describe the bag and show your name. Do not share anyone’s private information in the class chat.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["Someone left a bag here.","Does anyone know the owner?","I didn’t see anything inside."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Topilgan buyum egasini aniqlash uchun savollar bering.","seconds":50,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Topilgan buyum haqida uning shaxsiy ichidagi ma’lumotni ochmasdan e’lon yozing.","exit":[[{"id":"en-a2-16-exit0","